from collections import defaultdict

def canFinish_dfs(numCourses, prerequisites):
    graph = defaultdict(list)
    for a, b in prerequisites:
        graph[b].append(a)

    color = [0] * numCourses   # 0 白：未访问, 1 灰：递归栈中, 2 黑：已完成

    def dfs(u):
        if color[u] == 1:
            return False       # 遇到灰色节点 => 有环
        if color[u] == 2:
            return True        # 已完成，直接复用结论
        color[u] = 1
        for v in graph[u]:
            if not dfs(v):
                return False
        color[u] = 2
        return True

    return all(dfs(i) for i in range(numCourses))
